"""Source coverage, native visual decisions, and composition verification for this batch."""
import json,sys,hashlib,sqlite3
from pathlib import Path
W=Path(__file__).resolve().parent;ROOT=W.parents[2];sys.path.insert(0,str(ROOT))
from icon_set.model.icons.registry import create
from icon_set.scripts.compose import compose
from icon_set.scripts.primitive_status import init_primitive_status,set_status
rows=json.loads((W/'batch.json').read_text());c=json.loads((W/'candidates.json').read_text());qa=json.loads((W/'release-qa.json').read_text())
HOLD={1: ('Open-edged perspective cube and separate upward pointing hand with open wrist.', 'Earlier profile closes the cube edge and loses hand details. No complete separated cube-and-hand layout with legal spacing is verified within SUB32; both original subjects are retained for review.'), 4: ('Ukrainian hryvnia sign with two crossbars.', 'The shared glyph catalog does not contain the hryvnia character. A matching shared glyph is required; do not invent a one-off currency drawing.'), 5: ('Lao kip K symbol with horizontal crossbar.', 'The shared glyph catalog does not contain the kip character. Do not replace this currency with an unmodified letter K or invent a new glyph.'), 7: ('Lira symbol with curved top and two crossbars.', 'No matching two-crossbar lira glyph exists in the shared typeface catalog. A pound glyph would not preserve the source character.'), 9: ('Robotic hand with open wrist, curved wrist seam, upper finger joint and slanted lower finger joint.', 'Earlier profile closes the wrist and omits finger joint seams. No complete hand with all joint details has a verified 32px layout at fixed 4px stroke.'), 13: ('Two wireless arcs above a closed phone frame containing a dollar sign and footer divider.', 'Earlier profile omits one wireless arc, upper phone closure and footer. Restoring all these parts together with the shared dollar glyph has no verified complete layout within 32px.'), 15: ('Closed rounded phone frame, separate closed play triangle and footer divider.', 'The interior triangle must keep an open counter while remaining clear of the phone frame and footer. The available interior height has no verified complete layout with fixed 4px stroke and required spacing.'), 16: ('Two wireless arcs above a closed phone frame with pound sign and footer divider.', 'The shared typeface catalog lacks a pound glyph; the earlier profile also omits an arc and phone details. All original parts remain pending, without substituting a newly drawn currency symbol.'), 17: ('Landscape monitor, internal dollar sign, vertical stand and horizontal foot.', 'Earlier profile removes the stand foot and changes the landscape frame. A source-complete monitor with shared dollar glyph, stand and foot is not verified at fixed SUB32 size.'), 19: ('Open palm with thumb and four raised rounded fingers.', 'The raised fingers need legal separation without dropping a finger. Four parallel finger gaps cannot be retained in the available envelope at the required stroke and spacing; no complete layout is verified.'), 22: ('Pound sign with curved upper stroke, one crossbar and baseline.', 'No pound glyph exists in the shared typeface catalog. Retain the source for a shared-glyph repair rather than inventing a standalone character.'), 23: ('Three concentric open semicircular rainbow arcs.', 'Three semicircles need two six-unit centerline gaps plus an inner radius large enough to remain open. The resulting outer radius exceeds the 14-unit limit. Do not turn the inner arc into a dot or remove an arc.'), 26: ('Three rising rounded candlestick bodies, each with upper and lower wick.', 'Three open bodies and all six wicks have no verified source-faithful SUB32 layout with legal parallel spacing. Retain all three candles; no reduced chart was activated.'), 28: ('Rounded document with clipped upper-right corner and inner rectangle divided into two cells.', 'This source is a framed two-cell drawing, not text RTF. The nested frame and divider require more internal parallel spacing than the available envelope; no complete compliant candidate is verified.'), 29: ('Indian rupee character with two upper bars, curved bowl and diagonal lower leg.', 'The shared typeface catalog lacks the rupee character. Do not replace it with a new one-off currency glyph.'), 38: ('Enclosing circle and two-bar equals character.', 'The shared symbol-equals glyph has a width-to-gap ratio of 26:12. At the required eight-unit parallel gap its width exceeds the legal interior of the enclosing circle. The narrower draft passes geometry but distorts shared-glyph proportions, so it is not activated.'), 39: ('Enclosing circle and pound character.', 'The pound character is absent from the shared typeface catalog. The complete circle must be preserved; a plain standalone currency mark cannot replace this original.'), 41: ('Rounded tactic board containing two X marks, an open circle and curved upward arrow.', 'Earlier profile removes one X and closes the circle. No complete layout preserving both X marks, circle, arrow and surrounding frame has been verified at fixed 32px and 4px stroke.'), 49: ('Three repeated vertical lightning zigzags, each with two diagonal legs and horizontal middle.', 'The parallel diagonal legs of each bolt fail the eight-unit centerline spacing rule. Widening three complete bolts while keeping them separate exceeds this envelope; the draft is retained for review, not activated.')}

audit=[];accepted=[];compositions={}
for r in rows:
 n=r['number'];assert Path(r['source_path']).is_file()
 assert hashlib.sha256((ROOT/r['python_source']).read_bytes()).hexdigest()==r['parent_sha256']
 e=dict(r,parent_preserved=True,source_sha256=hashlib.sha256(Path(r['source_path']).read_bytes()).hexdigest())
 if str(n) in c:
  cand=c[str(n)];m=create(cand['icon']);sv=m.to_svg();q=qa[str(n)];assert q['svg_sha256']==hashlib.sha256(sv.encode()).hexdigest()
  e.update(candidate=cand['icon'],candidate_python=cand['python_source'],source_parts=cand['parts'],repair=cand['parts'],construction_reference=cand['lucide_reference'],candidate_status=q['status'],candidate_findings=q.get('errors',[])+q.get('warnings',[]))
  if q['status']!='pass' and n not in HOLD:HOLD[n]=(cand['parts'],'Candidate retained for another repair: '+'; '.join(e['candidate_findings']))
 if n in HOLD:
  parts,reason=HOLD[n];e.update(source_parts=parts,outcome='unresolved',primitive_status='skip',previous_variant_needs_review=True,reason=reason,source_coverage_pass=False)
 else:
  assert m.validate_icon().status=='valid'
  cq=compose('container-circle',cand['icon']).validate_icon()
  if getattr(m,'text_canvas_width',32)>32:
   assert m.text_canvas_width>32
   compositions[str(n)]={'icon':cand['icon'],'status':'not_applicable_wide_text','container_circle_status':cq.status,'findings':cq.describe(),'reason':'User explicitly requested natural-width shared-glyph text with 32px ink height. Container-circle placement is not compatible with this width; no scaling or glyph distortion applied. Validate its eventual side placement separately.'}
  else:
   assert cq.status=='valid',cq.describe()
   compositions[str(n)]={'icon':cand['icon'],'status':cq.status,'findings':cq.describe()}
  e.update(outcome='repaired',reason=cand['parts']+(' Natural-width text: square container placement is not applicable; side placement must accommodate its full width.' if getattr(m,'text_canvas_width',32)>32 else ''),source_coverage_pass=True,visual_review='Complete original compared with native light/dark renders and enlarged centerlines. Counts, directions, loops and frames retained. No human approval implied.')
  accepted.append(e)
 audit.append(e)
for name,data in [('audit',audit),('accepted',accepted),('composition-checks',compositions)]: (W/(name+'.json')).write_text(json.dumps(data,indent=2))
(W/'primitive-status.sqlite3').unlink(missing_ok=True)
con=sqlite3.connect(W/'primitive-status.sqlite3');init_primitive_status(con)
for e in audit:
 if e['outcome']=='unresolved':set_status(con,[e['source_uuid']],'skip','other',e['reason'],user='gpt-6',record=lambda *a,**k:None)
con.commit();con.close()
(W/'primitive-status.json').write_text(json.dumps({e['source_uuid']:{'status':'skip','icon':e['icon'],'note':e['reason']} for e in audit if e['outcome']=='unresolved'},indent=2))
print(len(accepted),'repaired;',50-len(accepted),'unresolved; all 50 original models preserved.')
